    export interface Agent {
        readonly id: SessionId;
        readonly options: AgentOptions;
        readonly session: Session;
        readonly inbox: Inbox;
        readonly status: AgentStatus;
        readonly ctx: Context;
        cancel(cause: AgentCancelCause, options?: CancelOptions): void;
        whenIdle(): Promise<void>;
        runMaintenance<T>(task: (signal: AbortSignal) => Promise<T>): Promise<T>;
        send(message: UserMessage, target: InboxTarget, wakeup: boolean): void;
        followup(message: UserMessage): void;
        steer(message: UserMessage): void;
        inject(message: UserMessage): void;
    }
    export type AgentCancelCause = {
        readonly kind: 'user';
    } | {
        readonly kind: 'parent';
    } | {
        readonly kind: 'hook';
        readonly reason: string;
    } | {
        readonly kind: 'disposed';
    };
    export interface AgentOptions {
        provider?: string;
        model?: string;
        maxTokens?: number;
    }
    export type AgentStatus = 'idle' | 'running';
    export interface AssistantMessage extends Message {
        readonly role: 'assistant';
        readonly source: ModelMessageSource;
    }
    export interface AssistantProvenance {
        provider: string;
        model: string;
        replayState?: unknown;
    }
    export type Branded<B extends string> = string & {
        readonly [BRAND]: B;
    };
    export type CallId = Branded<'CallId'>;
    export interface CancelOptions {
        keepInbox?: boolean | undefined;
    }
    export interface ContentBlockMap {
        'text': TextBlock;
        'reasoning': ReasoningBlock;
        'tool-call': ToolCallBlock;
        'tool-result': ToolResultBlock;
    }
    export type ContentBlockType = keyof ContentBlockMap;
    export type ContextFormed = {
        readonly form?: never;
    } | {
        readonly form: 'instructions';
    } | {
        readonly form: 'catalog';
    } | {
        readonly form: 'snapshot';
        readonly sections: readonly ContextSnapshotSection[];
    } | {
        readonly form: 'notice';
        readonly summary: string;
    } | {
        readonly form: 'relay';
    } | {
        readonly form: 'recall';
    };
    export interface ContextSnapshotSection {
        readonly name: string;
        readonly text: string;
    }
    export interface DiffCallView {
        card: 'diff';
        title: string;
        diffs: FileDiff[];
        locations?: FileLocation[];
    }
    export interface DiffResultView {
        card: 'diff';
        title?: string;
        diffs: FileDiff[];
    }
    export interface EpochHeader {
        config: LlmCallConfig;
        adapterDefaults?: LlmCallConfigAdapterDefaults;
        system?: string;
        tools?: ToolSchema[];
    }
    export interface FileDiff {
        path: string;
        oldText: string | null;
        newText: string;
    }
    export interface FileLocation {
        path: string;
        line?: number;
    }
    export type FinishReason = FinishReasonMap[keyof FinishReasonMap];
    export interface FinishReasonMap {
        'stop': {
            kind: 'stop';
        };
        'tool-calls': {
            kind: 'tool-calls';
        };
        'max-tokens': {
            kind: 'max-tokens';
        };
        'aborted': {
            kind: 'aborted';
            failure: LlmFailure;
        };
        'error': {
            kind: 'error';
            failure: LlmFailure;
        };
    }
    export interface GenericCallView {
        card: 'generic';
        title: string;
        kind?: ToolCallKind;
        rawInput?: unknown;
        content?: ContentBlock[];
        locations?: FileLocation[];
    }
    export interface GenericResultView {
        card: 'generic';
        title?: string;
        content?: ContentBlock[];
    }
    export class Inbox {
        constructor(private readonly session: Session, private readonly notifications: InboxNotifications);
        get nextTurn(): readonly UserMessage[];
        get nextStep(): readonly UserMessage[];
        get hasPending(): boolean;
        clear(): void;
        claim(target: InboxTarget, turn: number): UserMessage[];
        append(target: InboxTarget, message: UserMessage): void;
        prepend(target: InboxTarget, message: UserMessage): void;
        replace(messageId: MessageId, newMessage: UserMessage): boolean;
        remove(messageId: MessageId): boolean;
        splice(target: InboxTarget, start: number, deleteCount: number, inserted: UserMessage[]): UserMessage[];
    }
    export interface InboxNotifications {
        inserted(message: UserMessage): void;
        discarded(message: UserMessage): void;
        claimed(message: UserMessage, turn: number): void;
    }
    export type InboxTarget = 'next-turn' | 'next-step';
    export interface JsonSchemaNode {
        type?: JsonSchemaType;
        oneOf?: JsonSchemaNode[];
        properties?: Record<string, JsonSchemaNode>;
        required?: string[];
        additionalProperties?: boolean;
        items?: JsonSchemaNode;
        enum?: JsonSchemaScalar[];
        const?: JsonSchemaScalar;
        description?: string;
        title?: string;
        default?: JsonValue;
        examples?: JsonValue;
    }
    export type JsonSchemaScalar = string | number | boolean | null;
    export type JsonSchemaType = 'object' | 'array' | 'string' | 'number' | 'integer' | 'boolean' | 'null';
    export type JsonValue = null | boolean | number | string | JsonValue[] | {
        [key: string]: JsonValue;
    };
    export interface LlmCallConfig {
        provider: string;
        model: string;
        reasoningEffort?: ReasoningEffortId;
        temperature?: number;
        maxTokens?: number;
        stop?: string[];
    }
    export interface LlmCallConfigAdapterDefaults {
        reasoningEffort?: true;
        maxTokens?: true;
    }
    export interface LlmFailure {
        readonly message: string;
        readonly code: string;
        readonly status?: number;
        readonly providerRetryAfterMs?: number;
        readonly requestId?: ProviderRequestId;
    }
    export interface Message {
        readonly id: MessageId;
        readonly role: 'system' | 'user' | 'assistant';
        readonly content: ContentBlock[];
        readonly source: MessageSource;
    }
    export type MessageId = Branded<'MessageId'>;
    export type MessageSource = MessageSourceMap[keyof MessageSourceMap];
    export interface MessageSourceMap {
        user: {
            kind: 'user';
        };
        plugin: {
            kind: 'plugin';
            plugin: string;
        } & ContextFormed;
        model: ModelMessageSource;
        tool: ToolMessageSource;
    }
    export interface ModelMessageSource extends AssistantProvenance {
        kind: 'model';
    }
    export type ProviderRequestId = Branded<'ProviderRequestId'>;
    export interface ReadFileLine {
        number: number;
        text: string;
    }
    export interface ReadResultView {
        card: 'read';
        title?: string;
        path: string;
        offset: number;
        lines: ReadFileLine[];
        totalLines: number;
        lang?: string;
        content?: ContentBlock[];
    }
    export interface ReasoningBlock {
        type: 'reasoning';
        text: string;
    }
    export type ReasoningEffortId = Branded<'ReasoningEffortId'>;
    export interface RequestContext {
        provider: string;
        model: string;
        contextWindow?: number;
    }
    export type RequestHeaderReason = 'initial' | 'resume' | 'change';
    export type ScopeKey = object;
    export interface SearchFileMatches {
        path: string;
        matches: SearchLineMatch[];
    }
    export interface SearchLineMatch {
        lineNumber: number;
        line: string;
    }
    export interface SearchMatchesResultView {
        card: 'search';
        shape: 'matches';
        title?: string;
        files: SearchFileMatches[];
        truncated: boolean;
        total: number;
    }
    export interface SearchPathsResultView {
        card: 'search';
        shape: 'paths';
        title?: string;
        paths: string[];
        truncated: boolean;
        total: number;
    }
    export type SearchResultView = SearchMatchesResultView | SearchPathsResultView;
    export class Session {
        get surface(): SessionSurface;
        readonly header: SessionHeader;
        get id(): SessionId;
        readonly firstLiveSeq: number;
        static create(id: SessionId, seed?: readonly SessionEvent[], header?: SessionHeader): Session;
        static fromRestore(id: SessionId, seed: readonly SessionEvent[], header: SessionHeader): Session;
        get events(): readonly SessionEvent[];
        get seq(): number;
        append<T extends SessionEventType>(type: T, data: SessionEventMap[T], ...opts: T extends SurfaceEventType ? [
            opts: SurfaceIntent
        ] : [
        ]): SessionEvent<T>;
        requestHeader(): EpochHeader | undefined;
        requestContext(): RequestContext | undefined;
        deriveMessages(): Message[];
        deriveEventMessage(event: SessionEvent): Message | null;
    }
    export type SessionEvent<T extends SessionEventType = SessionEventType> = {
        [K in SessionEventType]: {
            type: K;
            seq: number;
            time: number;
            data: SessionEventMap[K];
        } & (K extends SurfaceEventType ? {
            sourceEventSeqs?: number[];
            surfaceOp?: SurfaceOp;
        } : object);
    }[T];
    export interface SessionEventMap {
        'turn/start': {
            turn: number;
        };
        'turn/end': {
            turn: number;
            reason: TurnEndReason;
        };
        'step/start': {
            turn: number;
            step: number;
        };
        'step/end': {
            turn: number;
            step: number;
        };
        'user/message': UserMessage;
        'assistant/chunk': {
            turn: number;
            step: number;
            chunk: StreamChunk;
        };
        'assistant/message': {
            turn: number;
            step: number;
            message: AssistantMessage;
            usage?: TokenUsage;
        };
        'tool/call': {
            turn: number;
            step: number;
            callId: CallId;
            name: string;
            arguments: string;
        };
        'tool/result': {
            turn: number;
            step: number;
            message: ToolResultMessage;
            error?: {
                name: string;
                code: string;
            };
            meta?: JsonValue;
        };
        'todo/write': {
            todos: TodoItem[];
        };
        'request/header': {
            header: EpochHeader;
            reason: RequestHeaderReason;
        };
        'request/context': RequestContext;
        'session/end-seed': Record<string, never>;
    }
    export type SessionEventType = keyof SessionEventMap;
    export interface SessionHeader {
        readonly version: number;
        readonly id: SessionId;
        readonly createdAt: number;
        readonly cwd?: string;
        readonly parentSession?: SessionId;
        readonly seedLength?: number;
        readonly origin?: 'subagent';
        readonly delegationDepth?: number;
    }
    export type SessionId = Branded<'SessionId'>;
    export interface SessionSurface {
        readonly nodes: readonly number[];
        readonly replaceGeneration: number;
    }
    export type StreamChunk = {
        type: 'block-start';
        index: number;
        blockType: ContentBlockType;
    } | {
        type: 'text-delta';
        index: number;
        text: string;
    } | {
        type: 'reasoning-delta';
        index: number;
        text: string;
    } | {
        type: 'tool-call-delta';
        index: number;
        id: CallId;
        name?: string;
        argumentsDelta: string;
    } | {
        type: 'block-end';
        index: number;
        block: ContentBlock;
    } | {
        type: 'usage';
        usage: TokenUsage;
    } | {
        type: 'finish';
        reason: FinishReason;
        replayState?: unknown;
    };
    export type SurfaceEventType = 'user/message' | 'assistant/message' | 'tool/result';
    export interface SurfaceIntent {
        surfaceOp: SurfaceOp;
        sourceEventSeqs?: number[];
    }
    export type SurfaceOp = 'append' | {
        op: 'replace';
        start: number;
        end: number;
    };
    export interface TerminalCallView {
        card: 'terminal';
        title: string;
        description?: string;
        cwd?: string;
    }
    export interface TerminalResultView {
        card: 'terminal';
        title?: string;
        output?: string;
        exitCode?: number;
        signal?: string;
    }
    export interface TodoItem {
        content: string;
        status: 'pending' | 'in_progress' | 'completed';
    }
    export interface TokenUsage {
        inputTokens: number;
        outputTokens: number;
        cacheReadTokens?: number;
        cacheWriteTokens?: number;
        reasoningTokens?: number;
    }
    export interface ToolCallBlock {
        type: 'tool-call';
        id: CallId;
        name: string;
        arguments: string;
    }
    export type ToolCallKind = 'read' | 'edit' | 'delete' | 'move' | 'search' | 'execute' | 'fetch' | 'other';
    export type ToolCallView = GenericCallView | TerminalCallView | DiffCallView;
    export interface ToolDefinition extends ToolSchema {
        readonly output: ToolOutputDefinition;
        execute(args: unknown, exec: ToolRunContext): Promise<unknown>;
        finalizeContent?(exec: Readonly<ToolExecution>, result: Readonly<ToolExecutionResult>): ContentBlock[] | undefined;
        timeoutMs?: number;
        isConcurrencySafe?(args: unknown): boolean;
        presentCall?(args: unknown): ToolCallView | undefined;
        presentResult?(args: unknown, result: ToolResult): ToolResultView | undefined;
    }
    export interface ToolErrorInfo {
        name: string;
        code: string;
    }
    export interface ToolExecution extends ToolExecutionInput {
        readonly rootCallId: CallId;
        readonly token: ToolExecutionToken;
    }
    export interface ToolExecutionFailure {
        readonly isError: true;
        readonly error: ToolFailure;
        readonly value?: never;
        readonly content: ContentBlock[];
        readonly meta?: JsonValue;
        readonly additionalContexts?: UserMessage[];
        readonly concludesTurn?: never;
    }
    export interface ToolExecutionInput {
        readonly callId: CallId;
        readonly rootCallId?: CallId;
        readonly name: string;
        readonly arguments: unknown;
        readonly agent?: Agent;
        readonly parent?: ToolExecutionToken;
        readonly signal: AbortSignal;
    }
    export type ToolExecutionMode = {
        kind: 'parallel';
    } | {
        kind: 'exclusive';
    };
    export type ToolExecutionResult = ToolExecutionSuccess | ToolExecutionFailure;
    export interface ToolExecutionSuccess {
        readonly isError: false;
        readonly value: JsonValue;
        readonly content: ContentBlock[];
        readonly error?: never;
        readonly meta?: JsonValue;
        readonly additionalContexts?: UserMessage[];
        readonly concludesTurn?: true;
    }
    export type ToolExecutionToken = symbol & {
        readonly [toolExecutionTokenBrand]: true;
    };
    export interface ToolFailure {
        message: string;
        info?: ToolErrorInfo;
    }
    export type ToolGuard = (execution: Readonly<ToolExecution>) => string | undefined;
    export interface ToolMessageSource {
        kind: 'tool';
        callId: CallId;
    }
    export interface ToolOutputDefinition {
        readonly schema: JsonSchemaNode;
        render(args: unknown, value: JsonValue): ContentBlock[];
        presentationMeta?(args: unknown, value: JsonValue): JsonValue;
    }
    export interface ToolRestriction {
        readonly allow?: readonly string[];
        readonly deny?: readonly string[];
    }
    export interface ToolResult {
        content: ContentBlock[];
        isError: boolean;
        meta?: JsonValue;
    }
    export interface ToolResultBlock {
        type: 'tool-result';
        toolCallId: CallId;
        content: ContentBlock[];
        isError?: boolean;
    }
    export interface ToolResultMessage extends Message {
        readonly role: 'user';
        readonly content: [
            ToolResultBlock
        ];
        readonly source: ToolMessageSource;
    }
    export type ToolResultView = GenericResultView | TerminalResultView | DiffResultView | SearchResultView | ReadResultView | WebResultView;
    export interface ToolRunContext extends ToolExecution {
        deferContext(context: UserMessage): void;
        concludeTurn(): void;
    }
    export interface ToolSchema {
        name: string;
        description: string;
        parameters: Record<string, unknown>;
    }
    export type TurnEndCancelCause = AgentCancelCause | {
        readonly kind: 'legacy';
    };
    export type TurnEndReason = TurnEndReasonMap[keyof TurnEndReasonMap];
    export interface TurnEndReasonMap {
        completed: {
            kind: 'completed';
        };
        aborted: {
            kind: 'aborted';
            reason: TurnEndCancelCause;
        };
        blocked: {
            kind: 'blocked';
        };
        error: {
            kind: 'error';
            error: LlmFailure;
        };
        'max-tokens': {
            kind: 'max-tokens';
        };
        interrupted: {
            kind: 'interrupted';
        };
    }
    export interface UserMessage extends Message {
        readonly role: 'user';
    }
    export interface WebFetchResultView {
        card: 'web';
        kind: 'fetch';
        title?: string;
        url: string;
        statusCode: number;
        truncated: boolean;
    }
    export type WebResultView = WebSearchResultView | WebFetchResultView;
    export interface WebSearchResultView {
        card: 'web';
        kind: 'search';
        title?: string;
        sources: WebSource[];
        answer?: string;
        truncated: boolean;
    }
    export interface WebSource {
        url: string;
        title?: string;
        snippet?: string;
        publishedAt?: string;
    }
